namespace NHAMBS.Cht

open System.IO
open FSharp.Data

/// Typed view of the history of bond purchases for cancellation associated with
/// one CHT series. The workbook linked from the outstanding amounts on the CMHC
/// debt-issues page contains one block per series; each block is parsed into its
/// own JSON document.
///
/// The provider reads
/// `schema/cmhc-cht-outstanding-history.provider.schema.json`, a flattened copy
/// of the real Draft 2020-12 schema. The copy is generated by
/// `generate-provider-schema.fsx` because FSharp.Data's schema reader does not
/// resolve `$ref`. The real schema remains the source of truth and is embedded
/// in this assembly for validation by `OutstandingHistorySchema.validate`.
type OutstandingHistory =
    JsonProvider<
        "",
        Schema="schema/cmhc-cht-outstanding-history.provider.schema.json",
        EmbeddedResource="NHAMBS.Cht, NHAMBS.Cht.schema.cmhc-cht-outstanding-history.provider.schema.json"
     >

[<RequireQualifiedAccess>]
module OutstandingHistory =

    /// Parse JSON that is already known to match the outstanding history schema.
    let parse (json: string) : OutstandingHistory.Root = OutstandingHistory.Parse json

    /// Validate JSON against the embedded schema, then parse it.
    let parseValidated (json: string) : Result<OutstandingHistory.Root, ValidationError list> =
        match OutstandingHistorySchema.validate json with
        | Error errors -> Error errors
        | Ok _ -> Ok(parse json)

    /// Load one outstanding history JSON file, validate it, and parse it.
    let load (path: string) : Result<OutstandingHistory.Root, ValidationError list> =
        File.ReadAllText path |> parseValidated

    /// Load a sequence of outstanding history files. Each result keeps its path.
    let loadMany (paths: string seq) =
        paths |> Seq.map (fun path -> path, load path) |> Seq.toArray

    /// Load every `*.json` file directly under a directory.
    let loadDirectory (directory: string) =
        Directory.EnumerateFiles(directory, "*.json") |> loadMany

    /// Small projection that is useful when indexing a history snapshot.
    let summary (history: OutstandingHistory.Root) =
        {|
            Series = history.Series
            AsOfDate = history.AsOfDate
            CancellationCount = history.Cancellations.Length
        |}
